      addInterface({ id: `${base}:interface:stimulus`, blockId: block.id, scopeNodeId: base, name: 'Simulation-only Program Bytes', category: 'simulation-stimulus', plane: 'data', sourceNodeId: intended.id, destinationNodeId: stimulus.id, semanticDescription: 'Conceptual association only: the testbench supplies bytes that stand in for an external program image.', rawConnectionIds: [], confidenceStatus: 'needs-review', notes: ['No memory-array or DDR timing behavior is modeled.'] })
