    const request = addNode({ id: `${base}:request`, blockId: block.id, parentId: base, displayName: 'Generic Read Request Contract', nodeType: 'external-interface', description: 'ready/valid + 64-bit address + 32-bit length + 8-bit ID.', rtlModuleRefs: ['lpu_top'], confidenceStatus: 'rtl-confirmed', sourceEvidence: [sourceEvidence('rtl/lpu_top.sv', 47, 'Program DMA request fields are top-level ports.')] })
    const response = addNode({ id: `${base}:response`, blockId: block.id, parentId: base, displayName: 'Generic Response Beat Contract', nodeType: 'external-interface', description: 'ready/valid + 256-bit data + 32-bit keep + last + 8-bit ID + error.', rtlModuleRefs: ['lpu_top'], confidenceStatus: 'rtl-confirmed', sourceEvidence: [sourceEvidence('rtl/lpu_top.sv', 52, 'Program DMA response fields are top-level ports.')] })
    const missing = addNode({ id: `${base}:missing`, blockId: block.id, parentId: base, displayName: 'AXI / C2C Adapter Not Modeled', nodeType: 'needs-review', description: 'No AXI AR/AW/W/R/B channel bundle, burst engine, DDR controller or C2C adapter module was found in the current filelist.', rtlModuleRefs: [], sourceKind: 'architectural-grouping', confidenceStatus: 'needs-review', tags: [{ label: 'DO NOT INFER', value: 'AXI FIVE-CHANNEL PROTOCOL' }] })
