    addNode({ id: `${counters.id}:mem`, blockId: block.id, parentId: counters.id, displayName: 'MEM Bank-local Counters · 0..207', architectureLevel: 'structural', nodeType: 'scheduler-counter-group', description: 'Two MEM hemispheres × 104 bank-local frontend/queue paths.', rtlModuleRefs: ['lpu_mem_subsystem'], confidenceStatus: 'rtl-confirmed', tags: [{ label: 'COUNT', value: '208' }] })
